{
  "examples": [
    {
      "question": "Quel est le résumé de la publication ayant l'identifiant le plus bas ?",
      "sql": "SELECT abstract FROM publication WHERE pid = (SELECT MIN(pid) FROM publication)"
    },
    {
      "question": "Combien d'années de publication différentes sont recensées ?",
      "sql": "SELECT count(DISTINCT year) FROM publication"
    },
    {
      "question": "Quel est le total des citations des publications de l'année la plus ancienne ?",
      "sql": "SELECT sum(citation_num) FROM publication WHERE citation_num >= (SELECT MIN(citation_num) FROM publication) AND year = (SELECT MIN(year) FROM publication)"
    },
    {
      "question": "Combien d'auteurs ayant l'identifiant le plus bas sont rattachés à chaque organisation ?",
      "sql": "SELECT count(*), oid FROM author WHERE aid = (SELECT MIN(aid) FROM author) GROUP BY oid"
    },
    {
      "question": "Affichez le nom de chaque auteur et le nom de son organisation.",
      "sql": "SELECT T1.name, T2.name FROM author AS T1 JOIN organization AS T2 ON T1.oid = T2.oid"
    },
    {
      "question": "Trouvez le nombre de publications.",
      "sql": "SELECT count(*) FROM publication"
    },
    {
      "question": "Quels sont les titres et les années de toutes les publications ?",
      "sql": "SELECT title, year FROM publication"
    },
    {
      "question": "Affichez l'identifiant, le continent et le nom de toutes les organisations, classées par nom.",
      "sql": "SELECT oid, continent, name FROM organization ORDER BY name"
    },
    {
      "question": "Quels sont les domaines associés à la publication qui possède le plus petit identifiant ?",
      "sql": "SELECT T2.name FROM domain_publication AS T1 JOIN domain AS T2 ON T1.did = T2.did WHERE T1.pid = (SELECT MIN(pid) FROM publication)"
    },
    {
      "question": "Listez les années au cours desquelles plus d'une publication a été publiée.",
      "sql": "SELECT year FROM publication GROUP BY year HAVING COUNT(*) > 1"
    },
    {
      "question": "Quels sont les différents domaines auxquels des auteurs sont rattachés ?",
      "sql": "SELECT DISTINCT T2.name FROM domain_author AS T1 JOIN domain AS T2 ON T1.did = T2.did"
    },
    {
      "question": "Affichez les noms des auteurs qui travaillent pour des organisations dont l'identifiant est positif.",
      "sql": "SELECT T2.name FROM writes AS T1 JOIN author AS T2 ON T1.aid = T2.aid JOIN organization AS T3 ON T2.oid = T3.oid WHERE T3.oid > 0"
    },
    {
      "question": "Affichez le nom des domaines associés à exactement une publication.",
      "sql": "SELECT T2.name FROM domain_publication AS T1 JOIN domain AS T2 ON T1.did = T2.did GROUP BY T1.did HAVING count(*) = 1"
    },
    {
      "question": "Listez tous les titres de publications par ordre alphabétique croissant.",
      "sql": "SELECT title FROM publication ORDER BY title"
    },
    {
      "question": "Combien d'auteurs ont l'identifiant le plus bas ?",
      "sql": "SELECT count(*) FROM author WHERE aid = (SELECT MIN(aid) FROM author)"
    },
    {
      "question": "Affichez chaque année de publication et le nombre de publications correspondantes.",
      "sql": "SELECT year, count(*) FROM publication GROUP BY year"
    }
  ]
}

{
  "examples": [
    {
      "question": "Combien d'aéronefs sont répertoriés pour chaque description parmi ceux dont l'identifiant est inférieur à 3 ?",
      "sql": "SELECT count(*), Description FROM aircraft WHERE Aircraft_ID < 3 GROUP BY Description"
    },
    {
      "question": "Affichez le nom de chaque aéroport ainsi que le nombre d'aéronefs qui lui sont associés.",
      "sql": "SELECT T1.Airport_Name, count(*) FROM airport AS T1 JOIN airport_aircraft AS T2 ON T1.Airport_ID = T2.Airport_ID GROUP BY T1.Airport_ID"
    },
    {
      "question": "Quels aéronefs ont remporté le plus grand nombre de manches ?",
      "sql": "SELECT DISTINCT COUNT(T1.Round), T2.Aircraft FROM match AS T1 JOIN aircraft AS T2 ON T1.Winning_Aircraft = T2.Aircraft_ID JOIN pilot AS T3 ON T1.Winning_Pilot = T3.Pilot_Id GROUP BY T2.Aircraft ORDER BY COUNT(T1.Round) DESC"
    },
    {
      "question": "Affichez le nombre maximal de passagers enregistré dans un aéroport.",
      "sql": "SELECT max(Total_Passengers) FROM airport"
    },
    {
      "question": "Quel est l'identifiant et le nom du pilote le plus âgé ?",
      "sql": "SELECT Pilot_Id, Name FROM pilot ORDER BY Age DESC LIMIT 1"
    },
    {
      "question": "Quel est le numéro de la manche disputée le plus récemment ?",
      "sql": "SELECT Round FROM match ORDER BY Date DESC LIMIT 1"
    },
    {
      "question": "Quel aéroport accueille le plus grand nombre de passagers ?",
      "sql": "SELECT Airport_Name FROM airport WHERE Total_Passengers = (SELECT MAX(Total_Passengers) FROM airport)"
    },
    {
      "question": "Quelle est la moyenne du nombre de passagers pour chaque aéronef associé à un aéroport, et quels sont les noms de ces aéronefs ?",
      "sql": "SELECT avg(T1.Total_Passengers), T3.Aircraft FROM airport AS T1 JOIN airport_aircraft AS T2 ON T1.Airport_ID = T2.Airport_ID JOIN aircraft AS T3 ON T3.Aircraft_ID = T2.Aircraft_ID GROUP BY T3.Aircraft"
    },
    {
      "question": "Quelle est la description de l'aéronef nommé « Robinson R-22 » ?",
      "sql": "SELECT Description FROM aircraft WHERE Aircraft = 'Robinson R-22'"
    },
    {
      "question": "Quel aéronef est associé à l'aéroport de Londres-Heathrow parmi les associations enregistrées avec l'identifiant 2 ?",
      "sql": "SELECT T2.Aircraft_ID FROM airport_aircraft AS T2 JOIN airport AS T1 ON T2.Airport_ID = T1.Airport_ID WHERE T1.Airport_Name = 'London Heathrow' AND T2.Aircraft_ID = 2"
    },
    {
      "question": "Quels pilotes ont remporté une manche à bord d'un Robinson R-22 ?",
      "sql": "SELECT T2.Name FROM match AS T1 JOIN pilot AS T2 ON T1.Winning_Pilot = T2.Pilot_Id JOIN aircraft AS T3 ON T3.Aircraft_ID = T1.Winning_Aircraft WHERE T3.Aircraft = 'Robinson R-22'"
    },
    {
      "question": "Quel pilote a remporté une manche avec l'aéronef ayant l'identifiant le plus élevé ?",
      "sql": "SELECT T1.Name FROM pilot AS T1 JOIN match AS T2 ON T1.Pilot_Id = T2.Winning_Pilot JOIN aircraft AS T3 ON T3.Aircraft_ID = T2.Winning_Aircraft ORDER BY T3.Aircraft_ID DESC LIMIT 1"
    },
    {
      "question": "Quels aéronefs ont remporté au moins deux manches et obtenu une somme de numéros de manche d'au moins 3 ?",
      "sql": "SELECT T1.Aircraft FROM aircraft AS T1 JOIN match AS T2 ON T1.Aircraft_ID = T2.Winning_Aircraft GROUP BY T1.Aircraft_ID HAVING count(*) >= 2 INTERSECT SELECT T1.Aircraft FROM aircraft AS T1 JOIN match AS T2 ON T1.Aircraft_ID = T2.Winning_Aircraft GROUP BY T1.Aircraft_ID HAVING sum(T2.Round) >= 3"
    },
    {
      "question": "Trouvez la description et le poids brut maximal de l'aéronef identifié par 2.",
      "sql": "SELECT Description, Max_Gross_Weight FROM aircraft WHERE Aircraft_ID = 2"
    },
    {
      "question": "Donnez le nom de chaque aéroport ainsi que l'identifiant des aéronefs qui y sont associés.",
      "sql": "SELECT T1.Airport_Name, T2.Aircraft_ID FROM airport AS T1 JOIN airport_aircraft AS T2 ON T1.Airport_ID = T2.Airport_ID"
    },
    {
      "question": "Quel aéroport possède le plus grand nombre d'associations avec des aéronefs ?",
      "sql": "SELECT T1.Airport_Name FROM airport AS T1 JOIN airport_aircraft AS T2 ON T1.Airport_ID = T2.Airport_ID GROUP BY T2.Airport_ID ORDER BY count(*) DESC LIMIT 1"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les prénoms des étudiants allergiques à la fois aux fruits de mer et au pollen des arbres ?",
      "sql": "SELECT T1.Fname FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID JOIN Allergy_Type AS T3 ON T2.Allergy = T3.Allergy WHERE T3.Allergy = 'Shellfish' INTERSECT SELECT T1.Fname FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID JOIN Allergy_Type AS T3 ON T2.Allergy = T3.Allergy WHERE T3.Allergy = 'Tree Pollen'"
    },
    {
      "question": "Quels sont les noms distincts des allergies de type alimentaire ?",
      "sql": "SELECT DISTINCT Allergy FROM Allergy_Type WHERE AllergyType = 'food'"
    },
    {
      "question": "Quels sont le prénom et le nom de famille de l'étudiant le plus âgé ?",
      "sql": "SELECT Fname, LName FROM Student ORDER BY Age ASC LIMIT 1"
    },
    {
      "question": "Quels sont les identifiants et les noms complets des étudiants qui suivent la même spécialité qu'une personne dont le prénom contient la lettre T ?",
      "sql": "SELECT StuID, Fname, LName FROM Student WHERE Major IN ( SELECT Major FROM Student WHERE Fname LIKE '%T%' )"
    },
    {
      "question": "Quel étudiant est le plus jeune ?",
      "sql": "SELECT StuID FROM Student ORDER BY Age ASC LIMIT 1"
    },
    {
      "question": "Quelles spécialités regroupent au moins deux étudiants ?",
      "sql": "SELECT Major FROM Student GROUP BY Major HAVING COUNT(*) >= 2"
    },
    {
      "question": "Quel type d'allergie est associé à Tracy pour son allergie aux fruits de mer ?",
      "sql": "SELECT DISTINCT T3.AllergyType FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID JOIN Allergy_Type AS T3 ON T2.Allergy = T3.Allergy WHERE T1.Fname = 'Tracy' AND T3.Allergy = 'Shellfish'"
    },
    {
      "question": "Quel est le nom de famille de l'étudiant le plus âgé ?",
      "sql": "SELECT LName FROM Student ORDER BY Age DESC ASC LIMIT 1"
    },
    {
      "question": "Quels étudiants de la ville BAL sont allergiques aux chats et ont plus de 17 ans ?",
      "sql": "SELECT T1.LName, T2.Allergy FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID WHERE T1.city_code = 'BAL' AND T2.Allergy = 'Cat' AND T1.Age > 17"
    },
    {
      "question": "Quels types d'allergies sont signalés pour Tracy ?",
      "sql": "SELECT AllergyType FROM Allergy_Type WHERE Allergy IN ( SELECT Allergy FROM Has_Allergy WHERE StuID = 1002 )"
    },
    {
      "question": "Combien de types d'allergies Tracy possède-t-elle ?",
      "sql": "SELECT COUNT ( DISTINCT T3.AllergyType ) FROM Has_Allergy AS T2 JOIN Student AS T1 ON T2.StuID = T1.StuID JOIN Allergy_Type AS T3 ON T2.Allergy = T3.Allergy WHERE T1.Fname = 'Tracy'"
    },
    {
      "question": "Donnez le nom et la ville de l'étudiant le plus âgé.",
      "sql": "SELECT LName, city_code FROM Student ORDER BY Age DESC LIMIT 1"
    },
    {
      "question": "Quels étudiants de plus de 17 ans vivent dans la même ville que l'étudiant le plus âgé ?",
      "sql": "SELECT Fname FROM Student WHERE Age > 17 AND city_code = ( SELECT city_code FROM Student WHERE Age = ( SELECT MAX ( Age ) FROM Student ) )"
    },
    {
      "question": "Comptez le nombre d'allergies de Tracy.",
      "sql": "SELECT count(*) FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID WHERE T1.Fname = 'Tracy'"
    },
    {
      "question": "À quel type appartient l'allergie aux œufs ?",
      "sql": "SELECT AllergyType FROM Allergy_Type WHERE Allergy = 'Eggs'"
    },
    {
      "question": "Quelles sont les allergies et la ville de Tracy ?",
      "sql": "SELECT T2.Allergy, T1.city_code FROM Student AS T1 JOIN Has_Allergy AS T2 ON T1.StuID = T2.StuID WHERE T1.Fname = 'Tracy'"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quel morceau a la durée la plus courte ?",
      "sql": "SELECT Name FROM Track WHERE Milliseconds = ( SELECT MIN ( Milliseconds ) FROM Track )"
    },
    {
      "question": "Quels sont les titres et les identifiants des albums d'AC/DC ?",
      "sql": "SELECT T2.Title, T2.AlbumId FROM Track AS T1 JOIN Album AS T2 ON T1.AlbumId = T2.AlbumId JOIN Artist AS T3 ON T2.ArtistId = T3.ArtistId WHERE T3.Name = 'AC/DC'"
    },
    {
      "question": "Quel morceau appartient à la playlist Music et porte l'identifiant 1 ?",
      "sql": "SELECT TrackId FROM PlaylistTrack WHERE PlaylistId = 1 AND TrackId = 1"
    },
    {
      "question": "Quels sont les noms des artistes qui ne sont pas AC/DC ?",
      "sql": "SELECT Name FROM Artist WHERE Name != 'AC/DC'"
    },
    {
      "question": "Combien de factures le client dont l'identifiant est 2 a-t-il reçues ?",
      "sql": "SELECT count(*) FROM Invoice AS T1 JOIN Customer AS T2 ON T1.CustomerId = T2.CustomerId WHERE T2.CustomerId = 2"
    },
    {
      "question": "Quelle ville et quel pays correspondent au plus petit nombre de factures ?",
      "sql": "SELECT BillingCity, BillingCountry FROM Invoice GROUP BY BillingCity, BillingCountry ORDER BY count(*) LIMIT 1"
    },
    {
      "question": "Quelle playlist contient le plus grand nombre de morceaux ?",
      "sql": "SELECT T2.Name FROM PlaylistTrack AS T1 JOIN Playlist AS T2 ON T1.PlaylistId = T2.PlaylistId GROUP BY T1.PlaylistId ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quels sont les trois premiers identifiants de genre selon la durée moyenne des morceaux, du plus long au plus court ?",
      "sql": "SELECT GenreId FROM Track GROUP BY GenreId ORDER BY avg(Milliseconds) DESC LIMIT 3"
    },
    {
      "question": "Quels artistes de rock ont plus de 10 morceaux ?",
      "sql": "SELECT T1.Name FROM Artist AS T1 JOIN Album AS T2 ON T1.ArtistId = T2.ArtistId JOIN Track AS T3 ON T2.AlbumId = T3.AlbumId JOIN Genre AS T4 ON T3.GenreId = T4.GenreId WHERE T4.Name = 'Rock' GROUP BY T1.Name HAVING COUNT ( DISTINCT T3.Name ) > 10"
    },
    {
      "question": "Listez les noms des trois morceaux les moins chers.",
      "sql": "SELECT Name FROM Track ORDER BY UnitPrice ASC LIMIT 3"
    },
    {
      "question": "Donnez-moi le nom et l'identifiant de chaque playlist.",
      "sql": "SELECT Name, PlaylistId FROM Playlist"
    },
    {
      "question": "Quel identifiant correspond au genre nommé « Rock » ?",
      "sql": "SELECT GenreId FROM Genre WHERE Name = 'Rock'"
    },
    {
      "question": "Quels artistes n'ont aucun album ? Listez leurs noms.",
      "sql": "SELECT Name FROM Artist WHERE ArtistId NOT IN ( SELECT ArtistId FROM Album )"
    },
    {
      "question": "Quels sont tous les noms de famille distincts des employés ?",
      "sql": "SELECT DISTINCT LastName FROM Employee"
    },
    {
      "question": "Quel est le nom complet de l'employé responsable du client Luís Gonçalves ayant reçu une facture ?",
      "sql": "SELECT DISTINCT T1.FirstName, T1.LastName FROM Employee AS T1 JOIN Customer AS T2 ON T1.EmployeeId = T2.SupportRepId JOIN Invoice AS T3 ON T2.CustomerId = T3.CustomerId WHERE T2.FirstName = 'Luís' AND T2.LastName = 'Gonçalves'"
    },
    {
      "question": "Quelle playlist est responsable du plus grand nombre de morceaux ?",
      "sql": "SELECT T1.Name FROM Playlist AS T1 JOIN PlaylistTrack AS T2 ON T1.PlaylistId = T2.PlaylistId GROUP BY T2.PlaylistId ORDER BY count(*) DESC LIMIT 1"
    }
  ]
}

{
  "examples": [
    {
      "question": "Donnez le nom et la capacité des cinémas situés dans le comté de Wicklow.",
      "sql": "SELECT Name, Capacity FROM cinema WHERE Location = 'County Wicklow'"
    },
    {
      "question": "Quel est le nom du cinéma associé à la date de programmation la plus récente ?",
      "sql": "SELECT T2.Name FROM schedule AS T1 JOIN cinema AS T2 ON T1.Cinema_ID = T2.Cinema_ID WHERE T1.Date = (SELECT max(Date) FROM schedule)"
    },
    {
      "question": "Quel est l'identifiant du cinéma qui propose le moins de séances quotidiennes pour un film ?",
      "sql": "SELECT Cinema_ID FROM schedule ORDER BY Show_times_per_day LIMIT 1"
    },
    {
      "question": "Quels sont la capacité, le lieu et le nom des 5 cinémas ayant les plus grandes capacités ?",
      "sql": "SELECT Capacity, Location, Name FROM cinema ORDER BY Capacity DESC LIMIT 5"
    },
    {
      "question": "Combien de cinémas ne programment aucun film ?",
      "sql": "SELECT count(*) FROM cinema WHERE Cinema_ID NOT IN (SELECT Cinema_ID FROM schedule)"
    },
    {
      "question": "Quel est le plus petit cinéma situé dans le même comté que le cinéma Codling ?",
      "sql": "SELECT Name FROM cinema WHERE Capacity = (SELECT MIN(Capacity) FROM cinema WHERE Location IN (SELECT Location FROM cinema WHERE Name = 'Codling')) AND Location IN (SELECT Location FROM cinema WHERE Name = 'Codling')"
    },
    {
      "question": "Trouvez les titres de tous les films réalisés par Bill Schreiner.",
      "sql": "SELECT Title FROM film WHERE Directed_by = 'Bill Schreiner'"
    },
    {
      "question": "Combien de cinémas ont ouvert en 2012 ou après ?",
      "sql": "SELECT count(*) FROM cinema WHERE Openning_year >= 2012"
    },
    {
      "question": "Quels sont les noms des cinémas qui programment plus d'un film ?",
      "sql": "SELECT T2.Name FROM schedule AS T1 JOIN cinema AS T2 ON T1.Cinema_ID = T2.Cinema_ID GROUP BY T1.Cinema_ID HAVING count(*) > 1"
    },
    {
      "question": "Quels sont les titres et les réalisateurs de tous les films ?",
      "sql": "SELECT Title, Directed_by FROM film"
    },
    {
      "question": "Quels sont les titres distincts des films dont le numéro de saison est compris entre 1 et 3 ?",
      "sql": "SELECT DISTINCT Title FROM film WHERE Number_in_season BETWEEN 1 AND 3"
    },
    {
      "question": "Quels sont les identifiants de tous les films programmés dans au moins un cinéma ?",
      "sql": "SELECT Film_ID FROM schedule"
    },
    {
      "question": "Quelles sont les années d'ouverture distinctes des cinémas qui programment des films réalisés par Bill Schreiner ?",
      "sql": "SELECT DISTINCT T1.Openning_year FROM cinema AS T1 JOIN schedule AS T2 ON T1.Cinema_ID = T2.Cinema_ID JOIN film AS T3 ON T2.Film_ID = T3.Film_ID WHERE T3.Directed_by = 'Bill Schreiner'"
    },
    {
      "question": "Trouvez le prix des séances proposées dans un cinéma dont le nom contient « od ».",
      "sql": "SELECT T2.Price FROM cinema AS T1 JOIN schedule AS T2 ON T1.Cinema_ID = T2.Cinema_ID WHERE T1.Name LIKE '%od%'"
    },
    {
      "question": "Affichez chaque cinéma et le nombre de films différents qui y sont programmés.",
      "sql": "SELECT T2.Name, COUNT(DISTINCT T1.Film_ID) FROM schedule AS T1 JOIN cinema AS T2 ON T1.Cinema_ID = T2.Cinema_ID GROUP BY T2.Name"
    },
    {
      "question": "Quels sont les noms des réalisateurs de films classés au rang 26, mais qui n'ont jamais réalisé le film intitulé « The Case: Off the Record » avec ce même rang ?",
      "sql": "SELECT DISTINCT Directed_by FROM film WHERE Rank_in_series = 26 EXCEPT SELECT DISTINCT Directed_by FROM film WHERE Rank_in_series = 26 AND Title = 'The Case: Off the Record'"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les identifiants de chaque club ainsi que le plus grand identifiant d'étudiant parmi ses membres ?",
      "sql": "SELECT ClubID, MAX(StuID) FROM Member_of_club GROUP BY ClubID"
    },
    {
      "question": "Quel club compte le moins de membres occupant le poste de président ?",
      "sql": "SELECT ClubID FROM Member_of_club WHERE Position = 'President' GROUP BY ClubID ORDER BY count(*) LIMIT 1"
    },
    {
      "question": "Quelle est la description et la localisation du club « Bootup Baltimore » ?",
      "sql": "SELECT ClubDesc, ClubLocation FROM Club WHERE ClubName = 'Bootup Baltimore'"
    },
    {
      "question": "Quels sont les noms des clubs dont le nom contient « Student » ?",
      "sql": "SELECT ClubName FROM Club WHERE ClubName LIKE '%Student%'"
    },
    {
      "question": "Quelle localisation regroupe le plus de participations étudiantes à des clubs ?",
      "sql": "SELECT T1.ClubLocation FROM Club AS T1 JOIN Member_of_club AS T2 ON T1.ClubID = T2.ClubID JOIN Student AS T3 ON T2.StuID = T3.StuID GROUP BY T1.ClubLocation ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quels sont les prénoms et noms des étudiants membres d'un club situé à AKW ?",
      "sql": "SELECT T1.Fname, T1.LName FROM Student AS T1 JOIN Member_of_club AS T2 ON T1.StuID = T2.StuID JOIN Club AS T3 ON T2.ClubID = T3.ClubID WHERE T3.ClubLocation = 'AKW'"
    },
    {
      "question": "Trouvez l'identifiant de l'étudiant et celui du club de la première adhésion selon l'identifiant du club.",
      "sql": "SELECT StuID, ClubID FROM Member_of_club ORDER BY ClubID LIMIT 1"
    },
    {
      "question": "Donnez-moi la description du club « Hopkins Student Enterprises ».",
      "sql": "SELECT ClubDesc FROM Club WHERE ClubName = 'Hopkins Student Enterprises'"
    },
    {
      "question": "Retournez les noms des étudiants âgés de plus de 20 ans.",
      "sql": "SELECT LName FROM Student WHERE Age > 20"
    },
    {
      "question": "Quels sont le nom et l'identifiant des trois premiers clubs selon leur identifiant ?",
      "sql": "SELECT ClubName, ClubID FROM Club ORDER BY ClubID ASC LIMIT 3"
    },
    {
      "question": "Triez toutes les localisations distinctes des clubs par ordre alphabétique.",
      "sql": "SELECT DISTINCT ClubLocation FROM Club ORDER BY ClubLocation"
    },
    {
      "question": "Quels sont les identifiants des étudiants qui ne sont membres d'aucun club ?",
      "sql": "SELECT StuID FROM Student EXCEPT SELECT StuID FROM Member_of_club"
    },
    {
      "question": "Quels sont les noms des clubs auxquels appartiennent des étudiants âgés de moins de 20 ans ?",
      "sql": "SELECT T3.ClubName FROM Student AS T1 JOIN Member_of_club AS T2 ON T1.StuID = T2.StuID JOIN Club AS T3 ON T2.ClubID = T3.ClubID WHERE T1.Age < 20"
    },
    {
      "question": "Listez les noms des clubs distincts, triés selon la somme des identifiants de leurs membres.",
      "sql": "SELECT T1.ClubName FROM Club AS T1 JOIN Member_of_club AS T2 ON T1.ClubID = T2.ClubID GROUP BY T1.ClubName ORDER BY sum(T2.StuID)"
    },
    {
      "question": "Quels sont les clubs qui n'ont qu'un seul membre ?",
      "sql": "SELECT ClubID FROM Member_of_club GROUP BY ClubID HAVING count(*) = 1"
    },
    {
      "question": "Quel club compte le membre féminin le plus jeune ?",
      "sql": "SELECT T1.ClubName FROM Club AS T1 JOIN Member_of_club AS T2 ON T1.ClubID = T2.ClubID JOIN Student AS T3 ON T2.StuID = T3.StuID WHERE T3.Sex = 'F' ORDER BY T3.Age ASC LIMIT 1"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quelle est la valeur budgétaire minimale, maximale et moyenne des départements ?",
      "sql": "SELECT min(budget), max(budget), avg(budget) FROM department"
    },
    {
      "question": "Combien d'inscriptions à des cours sont enregistrées ?",
      "sql": "SELECT count(*) FROM takes"
    },
    {
      "question": "Quels sont les noms des départements de génie civil ou de biologie ?",
      "sql": "SELECT dept_name FROM department WHERE dept_name = 'Civil Eng.' OR dept_name = 'Biology'"
    },
    {
      "question": "Combien d'enseignants conseillent des étudiants du département d'histoire ?",
      "sql": "SELECT COUNT ( DISTINCT T3.name ) FROM student AS T1 JOIN advisor AS T2 ON T1.ID = T2.s_ID JOIN instructor AS T3 ON T2.i_ID = T3.ID JOIN department AS T4 ON T3.dept_name = T4.dept_name WHERE T1.dept_name = 'History'"
    },
    {
      "question": "Quelle année compte le plus grand nombre de sections proposées ?",
      "sql": "SELECT year FROM section GROUP BY year ORDER BY count(*) DESC LIMIT 1"
    },
    {
